insert  into comunisecurity_param(param,value,note) values ('WSHOSTURL_ASPNET','http://vbg.aspnet/aspnet','E'' l''url di base dal quale partire per invocare i web service asp.net. L''url deve essere accedibile solo dalle singole applicazioni asp.net e java ed eventualmente http://10.10.45.2/aspnet per invocare i web service bisogna accodare all''url il percorso relativo del metodo da richiamare: \"WebServicesWSSIGeProSmtpMail SmtpMailSender.asmx\" che sarà hard coded.dal front-end.');
