insert  into comunisecurity_param(param,value,note) values ('WSHOSTURL_FILECONVERTER','http://vbg.fileconverter:9080/fileconverter/ws/fileconverter.wsdl','E'' l''url dell''host che espone il servizio di conversione file. L''url deve essere accedibile solo dalle singole applicazioni asp.net, java e dal front-end. Es: http://sigeprodemo:8080/fileconverter/services/fileconverter.wsdl');
