insert  into comunisecurity_param(param,value,note) values ('WSHOSTURL_JAVA','http://vbg.backend:8281/backend','E'' l''url di base dal quale partire per invocare i web service java. L''url deve essere accedibile solo dalle singole applicazioni asp.net e java ed eventualmente dal front-end. Es: http://10.10.45.2/sigepro2');
