insert  into comunisecurity_param(param,value,note) values ('WSHOSTURL_NLAPEC','http://devel9:8085/nla-pec/services/nlaGestioneMail.wsdl','E'' l''url dell''applicativo che gestisce i servizi di lettura di una casella email. L''applicativo espone sia servizi STC che servizi per leggere le mail di una casella PEC configurata nel backend ma questo parametro serve per accedere solamente ai servizi di lettura / processamento messaggi.Es. di configurazione: http://localhost:8080/nla-pec/services/nlaGestioneMail.wsdl');
