insert  into comunisecurity_param(param,value,note) values ('WSHOSTURL_PDFUTILS','http://devel9:8080/pdfutils/services/pdfutils?wsdl','E'' l''url dell''applicativo che gestisce i servizi di precompilazione / lettura dati da PDF compilabili. L''applicativo deve essere raggiungibile anche dalla macchina di frontoffice quindi verificare che dalla macchina del frontoffice questa configurazione sia raggiungibile.Es. di configurazione: http://nomemacchina:8080/pdfutils/services/pdfutils?wsdl');
insert  into comunisecurity_param(param,value,note) values ('WSHOSTURL_RENDER','http://devel9:8080/ibcwfrenderer/services/sigeprorendererSOAP?wsdl','E'' l''url dell''host che espone il servizio graficazione delle procedure. L''url deve essere accedibile solo dalle singole applicazioni asp.net, java e dal front-end. Es: http://localhost:9090/axis/services/sigeprorendererSOAP');
